// ==== Accesorios (grupo): aparecen con animacion y crecen con boca de beso ====
//
// Este script esta en el grupo, asi que afecta a todo lo que hay dentro.
// Cada funcion se llama sola cuando ocurre ese gesto. Cambia lo que hay dentro
// o deja la funcion vacia si no la necesitas.
//   this  -> el grupo Accesorios
//   face  -> la cara, con valores de 0 a 1: face.jawOpen, face.smile,
//            face.blink, face.browRaise y face.blendshapes.<nombre>
// face.blendshapes tiene las 52 expresiones de MediaPipe, por ejemplo:
//   mouthPucker (beso), mouthFunnel (boca en O), eyeWideLeft, eyeSquintLeft,
//   mouthLeft, mouthRight, browDownLeft, jawLeft, noseSneerLeft...
// En el editor solo se ejecutan start y update (alli `face` no existe).

let baseScale = 1;
let appear = 1; // 0 = recien aparecida la cara, 1 = animacion terminada
let kiss = 0;

// ---- Ciclo de vida -------------------------------------------------------

function start() {
	baseScale = this.scale.x;
}

// Cada fotograma: anima la entrada y aplica el tamaño del beso.
function update(event) {
	appear = Math.min(1, appear + event.delta / 400);
	const pop = 1 - Math.pow(1 - appear, 3); // empieza rapido y frena
	this.scale.setScalar(baseScale * Math.max(pop, 0.001) * (1 + kiss * 0.4));
}

// ---- Cara ----------------------------------------------------------------

// La cara aparece: los accesorios entran creciendo desde cero.
function faceFound(event) {
	appear = 0;
}

function faceLost(event) {
	// La cara sale de la camara (la web oculta la escena sola).
	kiss = 0;
}

// Cada fotograma con cara: poner boca de beso agranda los accesorios.
function faceUpdate(event) {
	kiss = face.blendshapes.mouthPucker ?? 0;
}

// ---- Boca ----------------------------------------------------------------

